app.UseRouting();
app.UseAuthentication();
app.UseAuthorization();

app.Map("/health", healthApp =>
{
    healthApp.Run(async context =>
    {
        context.Response.ContentType = "text/plain";
        await context.Response.WriteAsync("Healthy");
    });
});

app.MapControllers(); // /api/* still requires auth

app.UseWhen(
    context => context.Request.Headers.ContainsKey("X-Debug"),
    branch => branch.Use(async (context, next) =>
    {
        var log = context.RequestServices.GetRequiredService<ILoggerFactory>()
            .CreateLogger("Debug");
        log.LogWarning("Debug header present for {Path}", context.Request.Path);
        await next();
    }));

app.Use(async (context, next) =>
{
    if (context.Request.Path == "/favicon.ico")
    {
        context.Response.StatusCode = 404;
        return; // do NOT call next — short-circuit
    }
    await next();
});

// If UseAuthentication is ONLY on main branch AFTER Map:
app.Map("/internal", internalApp =>
{
    internalApp.MapControllers(); // NO auth middleware in this branch!
});

// Fix: register auth inside Map branch or use endpoint filters
internalApp.UseAuthentication();
internalApp.UseAuthorization();
